"""Axisymmetric circular membrane: complete independent reading paths."""
def populate(add,C,M,table):
    add(12,'Circular membrane(원형 막) · 극좌표와 축대칭',[
      C('극좌표에서는 원형 테두리가 r=R입니다.', M(r'x=r\cos\theta,\quad y=r\sin\theta,\qquad u_{tt}=c^2\left(u_{rr}+\frac1r u_r+\frac1{r^2}u_{\theta\theta}\right)'), 'Polar coordinates(극좌표)에서 r은 중심까지 거리, θ는 평면의 회전각입니다. 원형 경계는 r=R 하나로 표현되어 편리합니다. 원형이라는 이유만으로 각도 의존성이 사라지는 것은 아닙니다.'),
      C('원본은 axisymmetric motion(축대칭 운동)을 다룹니다.', M(r'u=u(r,t),\qquad u_{tt}=c^2\left(u_{rr}+\frac1r u_r\right),\quad 0<r<R'), M(r'u(R,t)=0,\quad u(r,0)=f(r),\quad u_t(r,0)=g(r)'), '각도에 무관한 초기변위·초기속도, 균일한 물성·고정 테두리 아래 θ에 무관한 해를 구합니다. 중심은 변위가 유한하고 매끄러워야 하며 uᵣ(0,t)=0입니다. 중심 변위 자체가 0이라는 조건은 없습니다. r=0의 1/r은 정칙해의 극한으로 해석합니다.'),
      C('왜 1/r 항이 추가되나요?', M(r'u_{rr}+\frac1r u_r=\frac1r\frac{\partial}{\partial r}(r u_r)'), '반지름 r인 얇은 고리의 둘레가 2πr에 비례하므로 반지름이 다른 두 면의 기여를 같은 폭의 직선처럼 빼면 안 됩니다. 둘레 인자 r을 포함해 미분한 뒤 r로 나누면 이 항이 나옵니다. 직선의 uₓₓ를 그대로 uᵣᵣ로 바꾸는 것만으로는 원형 문제를 풀 수 없습니다.')
    ],[
      C('1 · 네모 격자 대신 중심에서의 거리를 씁니다.', 'Circular membrane(원형 막)은 북처럼 둥근 막입니다. 테두리를 x,y로 쓰면 x²+y²=R²이지만 polar coordinates(극좌표)로 쓰면 r=R입니다. r은 중심에서 얼마나 멀리 떨어졌는지, θ는 어느 방향인지를 나타냅니다.', M(r'x=r\cos\theta,\qquad y=r\sin\theta'), '원 안의 모든 점은 거리와 방향으로 표시할 수 있습니다. 이렇게 좌표를 바꾸어도 같은 물리 문제지만 미분의 모양은 달라집니다.'),
      C('2 · 둥글다고 모든 진동이 원형 대칭인 것은 아닙니다.', '한쪽만 눌렀다면 같은 반지름에서도 방향마다 높이가 다를 수 있습니다. 원본은 axisymmetric(축대칭), 즉 처음 모양과 속도가 오직 r에만 달린 경우를 풉니다. 그래서 같은 원 위의 점들은 함께 움직이고 θ 미분은 0입니다.', M(r'u_{tt}=c^2\left(u_{rr}+\frac1r u_r+\frac1{r^2}u_{\theta\theta}\right)\ \longrightarrow\ u_{tt}=c^2\left(u_{rr}+\frac1r u_r\right)'), '생략되는 것은 θ 항뿐입니다. 거리 r에 따른 변화는 여전히 남습니다.'),
      C('3 · 원의 둘레가 커지는 효과를 포함합니다.', '얇은 고리는 바깥쪽 둘레가 안쪽보다 깁니다. 따라서 두 방향의 차이를 계산할 때 반지름에 비례하는 인자를 넣어야 합니다. 곱의 미분을 펼치면 익숙한 두 항을 얻습니다.', M(r'\frac1r(r u_r)_r=\frac1r(u_r+r u_{rr})=\frac1r u_r+u_{rr}'), '1/r 항은 임의로 붙인 보정이 아니라 좌표의 기하에서 나옵니다.'),
      C('4 · 테두리는 고정하지만 중심은 움직여도 됩니다.', M(r'u(R,t)=0,\quad u(r,0)=f(r),\quad u_t(r,0)=g(r)'), 'Boundary condition(경계조건)은 바깥 테두리에 적용합니다. 중심에는 못을 박지 않았으므로 u(0,t)=0을 추가하지 않습니다. 대신 중심에서 높이가 무한대가 되거나 뾰족하게 꺾이면 매끄러운 막이 아니므로 finite(유한)하고 uᵣ(0,t)=0인 해를 고릅니다. 이 조건이 다음의 두 베셀 함수 중 하나를 제외합니다.')
    ])

    add(13,'Bessel equation(베셀 방정식) · 낯선 함수가 나오는 이유',[
      C('변수분리와 무차원 치환', M(r'u=W(r)G(t)\quad\Rightarrow\quad\frac{W^{\prime\prime}+W^\prime/r}{W}=\frac{G^{\prime\prime}}{c^2G}=-k^2'), M(r'G^{\prime\prime}+c^2k^2G=0,\qquad r^2W^{\prime\prime}+rW^\prime+k^2r^2W=0'), M(r's=kr,\quad W(r)=Z(s),\quad W^\prime=kZ^\prime,\quad W^{\prime\prime}=k^2Z^{\prime\prime}'), M(r'\boxed{s^2Z^{\prime\prime}+sZ^\prime+s^2Z=0}'), 'Bessel equation(베셀 방정식) s²Z″+sZ′+(s²−ν²)Z=0의 order(차수) ν=0입니다. k의 단위가 1/길이이므로 s=kr는 무차원입니다. 시간 해는 A cos(ckt)+B sin(ckt)입니다.'),
      C('중심 정칙성이 허용하는 함수', M(r'W=CJ_0(kr)+DY_0(kr),\qquad D=0'), 'J₀는 Bessel function of the first kind(제1종 베셀 함수), Y₀는 second kind(제2종)입니다. J₀(0)=1이고 J₀′(0)=0인 반면 Y₀는 원점에서 로그 형태로 발산합니다. 중심을 포함한 막에서는 Y₀를 제외합니다. 이는 테두리 조건과 별개의 regularity condition(정칙성 조건)입니다.'),
      C('J₀는 계산 규칙이 있는 함수입니다.', M(r'J_0(s)=\sum_{j=0}^{\infty}\frac{(-1)^j(s^2/4)^j}{(j!)^2}=1-\frac{s^2}4+\frac{s^4}{64}-\frac{s^6}{2304}+\cdots'), 'cos s가 1−s²/2!+s⁴/4!−…로 정의되듯 J₀도 급수로 계산할 수 있습니다. 사인을 잘못 쓴 것이 아니라 원형 기하의 ODE를 만족하는 다른 함수입니다. 식과 차수의 정의는 <a href="https://dlmf.nist.gov/10.2">NIST DLMF §10.2</a>와 대조했습니다.')
    ],[
      C('1 · 공간 모양과 시간 배율을 또 나눕니다.', 'Separation of variables(변수분리법)의 순서는 직사각형 때와 같습니다. u=W(r)G(t)를 넣으면 r 미분은 W만, t 미분은 G만 건드립니다.', M(r'WG^{\prime\prime}=c^2(W^{\prime\prime}+W^\prime/r)G'), M(r'\frac{W^{\prime\prime}+W^\prime/r}{W}=\frac{G^{\prime\prime}}{c^2G}=-k^2'), '따라서 시간은 G″=−c²k²G가 되어 사인·코사인입니다. 공간은 W″+(1/r)W′+k²W=0입니다. 원형 기하에서 생긴 W′/r 때문에 단순 사인은 일반적으로 이 공간 방정식의 해가 아닙니다.'),
      C('2 · 치환은 낯선 상수 k를 식에서 정리하는 도구입니다.', 's=kr로 두고 같은 공간 함수를 새 변수 s로 쓴 것이 Z(s)입니다. Chain rule(연쇄법칙)에 따라 r로 한 번 미분할 때 ds/dr=k가 한 번 붙습니다.', M(r'W(r)=Z(kr),\quad\frac{dW}{dr}=k\frac{dZ}{ds},\quad\frac{d^2W}{dr^2}=k^2\frac{d^2Z}{ds^2}'), M(r'r^2 k^2Z^{\prime\prime}+rkZ^\prime+k^2r^2Z=0\quad\Rightarrow\quad s^2Z^{\prime\prime}+sZ^\prime+s^2Z=0'), '이 표준 ODE의 이름이 Bessel equation(베셀 방정식)입니다. J₀와 Y₀는 이 방정식을 푸는 두 독립 함수의 이름입니다. 답이 갑자기 주어진 것이 아니라, 이미 연구된 방정식 형태까지 계산을 정리한 것입니다.'),
      C('3 · J₀라는 이름을 외우기 전에 중심 값을 확인합니다.', M(r'J_0(s)=1-\frac{s^2}4+\frac{s^4}{64}-\frac{s^6}{2304}+\cdots'), 's=0을 넣으면 첫 항 1만 남고, 미분하면 모든 항에 s가 남아 J₀′(0)=0입니다. 중심 높이와 기울기가 모두 정상입니다. 반면 Y₀는 s가 0에 가까워질수록 로그처럼 발산하므로 실제 막의 중심 변위를 표현할 수 없습니다.', M(r'W=CJ_0(kr)+DY_0(kr)\quad\longrightarrow\quad W=CJ_0(kr)'), 'Regularity(정칙성)는 여기서 중심에 이상한 무한대나 뾰족한 점이 생기지 않는다는 요구입니다. 상수 C는 나중에 시간 앞의 진폭 계수에 합칩니다.'),
      C('4 · 급수의 숫자도 ODE에서 나옵니다.', 'Z=a₀+a₁s+a₂s²+…를 ODE에 넣어 같은 거듭제곱의 계수를 비교하면 다음을 얻습니다.', M(r'a_1=0,\qquad j^2a_j+a_{j-2}=0\ (j\ge2)'), M(r'a_0=1\ \Rightarrow\ a_2=-\frac14,\quad a_4=\frac1{64},\quad a_6=-\frac1{2304}'), 'a₁=0이므로 홀수 차수는 모두 0이고, 짝수 계수는 차례로 정해집니다. 정규화 a₀=1을 택한 해가 J₀입니다. 0이라는 아래첨자는 함수의 order(차수)이며 진동 모드 번호가 아닙니다.')
    ])

    add(15,'원형 테두리의 고정 조건 · 베셀 함수의 영점',[
      C('J₀의 양의 영점으로 모드를 고릅니다.', M(r'W(R)=0\quad\Rightarrow\quad J_0(kR)=0'), M(r'J_0(\alpha_m)=0,\quad0<\alpha_1<\alpha_2<\cdots,\quad k_m=\frac{\alpha_m}{R}'), M(r'W_m(r)=J_0\!\left(\frac{\alpha_m r}{R}\right),\qquad \lambda_m=ck_m=\frac{c\alpha_m}{R}'), 'αₘ는 J₀의 m번째 positive zero(양의 영점)입니다. 직사각형의 sin(kL)=0에서 kL=nπ를 골랐던 것과 같은 역할입니다. J₀(0)=1이므로 0은 영점이 아닙니다.'),
      C('0 모드와 발산해를 남기지 않습니다.', 'k=0이면 공간식은 (rW′)′=0이고 W=A ln r+B입니다. 중심 정칙성으로 A=0, 테두리 고정으로 B=0이므로 비영 정지 모드가 없습니다. k²<0도 정칙해와 고정 테두리를 동시에 만족하는 비영 해가 없습니다.', M(r'\int_0^R r(W^\prime)^2\,dr=k^2\int_0^R rW^2\,dr'), '공간 ODE에 W를 곱해 적분하고 경계항을 없애면 위 식입니다. 비영 해에서는 오른쪽의 노름이 양수이므로 k²가 음수일 수 없습니다. 따라서 양의 영점만 사용합니다.')
    ],[
      C('1 · 원형 막도 테두리에서 높이가 0이어야 합니다.', '공간 모양 J₀(kr)에 r=R을 넣습니다. 배율을 0으로 만들면 진동 자체가 없어지므로 함수가 0이 되는 입력을 찾아야 합니다.', M(r'J_0(kR)=0'), 'Sine(사인)은 입력이 π,2π,…일 때 0이 됩니다. J₀도 0이 되는 입력들이 있지만 정확히 π의 정수배는 아닙니다. 그 값을 α₁,α₂,…라고 부릅니다.'),
      C('2 · 영점의 입력과 실제 반지름은 다릅니다.', M(r'k_mR=\alpha_m\quad\Rightarrow\quad k_m=\frac{\alpha_m}{R}'), M(r'W_m(r)=J_0(\alpha_m r/R),\qquad G_m=A_m\cos(\lambda_m t)+B_m\sin(\lambda_m t),\quad\lambda_m=\frac{c\alpha_m}{R}'), 'r=R이면 함수 입력이 딱 αₘ이 되어 테두리 변위가 0입니다. 반지름이 커지면 같은 모드를 더 넓게 펼치므로 k와 angular frequency(각진동수)가 작아집니다. 시간 주기는 2πR/(cαₘ)입니다.'),
      C('3 · 왜 m=1부터인가요?', 'J₀(0)=1이라 입력 0은 zero(영점)가 아닙니다. k=0을 따로 풀면 W=A ln r+B인데, 중심에서 무한대가 되지 않으려면 A=0, 테두리에서 0이려면 B=0입니다. 결국 진동 재료로 쓸 수 있는 비영 모드는 없습니다.', M(r'm=1,2,3,\ldots\qquad\text{(positive zeros of }J_0\text{)}'), '직사각형 모드도 1부터였지만 구면 문제의 Legendre polynomial(르장드르 다항식)은 0부터입니다. 번호를 통째로 외우기보다 0번 함수가 실제로 허용되는지 경계조건으로 확인합니다.')
    ])

    add(16,'J₀ 그래프 읽기 · 함수 차수와 모드 번호',[
      C('가로축은 베셀 함수의 무차원 입력입니다.', table(['m','αₘ: J₀의 양의 영점','내부 nodal circle(마디원) 개수'],[('1','2.404825558','0'),('2','5.520078110','1'),('3','8.653727913','2'),('4','11.791534439','3')]), '표의 수치는 편집자 수치 보강입니다. 원본 그래프의 음의 입력은 J₀의 함수 모양을 보여 줍니다. 물리적 반지름은 r≥0이고 kₘ>0을 사용합니다. J₀는 짝함수지만 음의 영점을 별도 막 모드로 세지 않습니다.'),
      C('내부 영점은 움직이지 않는 동심원입니다.', M(r'r_j=R\frac{\alpha_j}{\alpha_m},\qquad j=1,\ldots,m-1'), 'm번째 모드의 입력은 중심의 0부터 테두리의 αₘ까지 증가합니다. 그 사이에 α₁,…,αₘ₋₁을 지나므로 내부 마디원이 m−1개입니다. J₀의 0은 order(차수), αₘ의 m은 zero index(영점 번호)입니다. J₁은 첫 번째 모드가 아니라 1차 베셀 함수입니다.')
    ],[
      C('1 · 그래프의 0을 지나는 위치를 읽습니다.', '원본의 그래프는 J₀(s)입니다. s=0에서 1로 시작하고 내려가며 약 2.4048에서 처음 0이 됩니다. 이후 부호를 바꾸며 여러 번 0을 지납니다. 이 입력들이 positive zeros(양의 영점) αₘ입니다.', M(r'\alpha_1\simeq2.404825558,\quad\alpha_2\simeq5.520078110,\quad\alpha_3\simeq8.653727913'), '사인처럼 일정한 간격이라고 가정하여 αₘ=mπ로 넣으면 경계조건이 맞지 않습니다. 실제 영점은 수치적으로 구하거나 표를 사용합니다.'),
      C('2 · 첫 모드는 중심에서 테두리까지 한 번만 내려갑니다.', '첫 모드는 J₀(α₁r/R)입니다. 중심 r=0에서 1이고, 테두리 r=R에서 처음으로 0이 됩니다. 안쪽에 0을 지나는 곳이 없어 내부 nodal circle(마디원)이 없습니다. 두 번째 모드는 입력이 α₂까지 진행하므로 도중에 α₁을 지납니다.', M(r'\frac{\alpha_2r}{R}=\alpha_1\quad\Rightarrow\quad r=\frac{\alpha_1}{\alpha_2}R\simeq0.43565R'), '그 동심원에서는 공간 함수가 0이므로 시간 배율이 무엇이든 변위가 0입니다. 중심과 바깥 고리는 서로 반대 부호로 움직일 수 있습니다.'),
      C('3 · 아래첨자 두 종류를 섞지 않습니다.', M(r'J_{\underbrace{0}_{\text{함수 차수}}}\!\left(\frac{\alpha_{\underbrace{m}_{\text{영점 번호}}}r}{R}\right)'), '이번 축대칭 문제의 공간 모드는 전부 J₀입니다. 모드가 바뀌면 J₁,J₂로 바꾸는 것이 아니라 α₁,α₂,…를 넣습니다. 뒤의 계수 공식에 나오는 J₁은 미분 관계 J₀′=−J₁ 때문에 등장하는 다른 차수의 함수입니다.')
    ])

    add(17,'Fourier–Bessel series(푸리에–베셀 급수) · 초기조건 맞추기',[
      C('축대칭 해를 중첩합니다.', M(r'u(r,t)=\sum_{m=1}^{\infty}[A_m\cos(\lambda_mt)+B_m\sin(\lambda_mt)]J_0(\alpha_m r/R),\qquad\lambda_m=c\alpha_m/R'), '원본은 모드와 중첩 해를 제시합니다. 아래 계수 적분은 생략된 initial conditions(초기조건) 적용을 완성한 것입니다. f(r),g(r)의 구체식이 없으므로 이 적분식이 일반적인 답입니다.'),
      C('직교성의 가중함수는 r입니다.', M(r'(rW_m^\prime)^\prime+k_m^2rW_m=0'), M(r'(k_m^2-k_n^2)\int_0^RrW_mW_n\,dr=\left[r(W_mW_n^\prime-W_nW_m^\prime)\right]_0^R=0\quad(m\ne n)'), '끝점 R에서는 W=0, 중심에서는 정칙성 및 r 인자로 경계항이 없어집니다. 따라서 weighted orthogonality(가중 직교성)는 dr가 아니라 r dr에서 성립합니다. 원의 고리 면적 2πr dr에서 공통 2π를 제외한 인자이기도 합니다.'),
      C('노름으로 나눈 계수', M(r'N_m=\int_0^RrJ_0^2(\alpha_mr/R)\,dr=\frac{R^2}{2}J_1(\alpha_m)^2'), M(r'\boxed{A_m=\frac{2}{R^2J_1(\alpha_m)^2}\int_0^Rr f(r)J_0(\alpha_mr/R)\,dr}'), M(r'\boxed{B_m=\frac{2}{\lambda_mR^2J_1(\alpha_m)^2}\int_0^Rr g(r)J_0(\alpha_mr/R)\,dr}'), 'J₁은 1차 베셀 함수입니다. t=0에서 Aₘ가 변위를, λₘBₘ가 속도를 맞춥니다. g=0이면 Bₘ=0입니다. <a href="https://dlmf.nist.gov/10.22.E37">NIST DLMF 10.22.37</a>의 ν=0 직교·노름식에 J₀′=−J₁과 r/R 치환을 적용했습니다.'),
      C('노름에 R²가 생기는 이유', M(r's=\alpha_mr/R\quad\Rightarrow\quad r\,dr=\frac{R^2}{\alpha_m^2}s\,ds'), M(r'\int_0^{\alpha_m}sJ_0(s)^2ds=\left[\frac{s^2}{2}\{J_0(s)^2+J_1(s)^2\}\right]_0^{\alpha_m}=\frac{\alpha_m^2}{2}J_1(\alpha_m)^2'), '원점에서는 s² 인자, 위끝에서는 J₀(αₘ)=0을 사용했습니다. 식의 R²와 J₁의 제곱은 임의의 상수가 아닙니다. 해의 정칙성·수렴은 초기 데이터의 조건과 함께 해석합니다.')
    ],[
      C('1 · 원형 막에서도 처음 모양을 부품으로 나눕니다.', '직사각형에서는 사인 곱이 부품이었고, 지금은 J₀(αₘr/R)이 부품입니다. 각 부품에 시간 코사인·사인 배율을 붙이고 모두 더합니다.', M(r'u=\sum_{m\ge1}[A_m\cos(\lambda_mt)+B_m\sin(\lambda_mt)]J_0(\alpha_mr/R)'), 't=0을 넣으면 f=ΣAₘJ₀입니다. 따라서 목표는 f가 각 Bessel mode(베셀 모드)를 얼마나 포함하는지 구하는 것입니다. 원본에는 구체적인 f,g가 없으므로 특정 모양을 새로 지어내지는 않고 일반 계수까지 구합니다.'),
      C('2 · 원에서는 바깥쪽 한 칸에 더 많은 면적이 있습니다.', '반지름 r의 얇은 고리 면적은 둘레×두께, 즉 2πr dr입니다. 같은 dr라도 바깥쪽 고리는 더 넓습니다. 따라서 모드를 비교할 때 r을 곱한 weighted inner product(가중 내적)를 써야 합니다.', M(r'\langle F,H\rangle=\int_0^Rr F(r)H(r)\,dr'), '서로 다른 모드에는 이 내적이 0입니다. 이는 직사각형에서 다른 사인끼리 곱해 적분하면 0이었던 역할과 같습니다. r을 빼면 일반적으로 직교성이 깨집니다. 공통 2π는 분자·분모에서 약분됩니다.'),
      C('3 · 곱하고 적분한 뒤 자기 크기로 나눕니다.', M(r'\int_0^Rr f(r)J_0(\alpha_mr/R)\,dr=A_m\underbrace{\int_0^RrJ_0^2(\alpha_mr/R)\,dr}_{N_m}'), M(r'N_m=\frac{R^2}{2}J_1(\alpha_m)^2,\qquad A_m=\frac{2}{R^2J_1(\alpha_m)^2}\int_0^Rr f(r)J_0(\alpha_mr/R)\,dr'), '다른 번호의 항은 직교성으로 없어지고 m번째 항만 남습니다. Nₘ은 같은 모드를 제곱해 적분한 양수입니다. 사인에서는 L/2였던 값이 여기서는 R²J₁(αₘ)²/2로 바뀝니다. J₁은 “첫 모드”가 아니라 1차 베셀 함수이고, 그 값 전체를 제곱합니다.'),
      C('4 · R²와 J₁이 어디에서 나왔는지 확인합니다.', M(r's=\alpha_mr/R,\quad r=Rs/\alpha_m,\quad dr=(R/\alpha_m)ds'), M(r'N_m=\frac{R^2}{\alpha_m^2}\int_0^{\alpha_m}sJ_0(s)^2\,ds=\frac{R^2}{\alpha_m^2}\frac{\alpha_m^2}{2}J_1(\alpha_m)^2'), 'r과 dr에서 R/αₘ가 각각 하나씩 나와 R²/αₘ²가 됩니다. 나머지는 베셀 함수의 표준 적분식입니다. 위끝이 영점이라 J₀ 항이 없어지고 J₁² 항이 남습니다. 이 특수함수 적분은 새로 외울 삼각함수 법칙이 아니라 해당 모드의 노름 공식으로 사용하면 됩니다.'),
      C('5 · 처음 속도에는 λ가 한 번 더 있습니다.', M(r'u_t(r,0)=\sum_{m\ge1}\lambda_mB_mJ_0(\alpha_mr/R)=g(r)'), M(r'B_m=\frac{2}{\lambda_mR^2J_1(\alpha_m)^2}\int_0^Rr g(r)J_0(\alpha_mr/R)\,dr'), 'sin(λt)를 미분하면 λcos(λt)이므로 λBₘ가 속도의 계수입니다. 따라서 Bₘ를 구할 때 λ로 나눕니다. Initially at rest(처음에 정지)이면 g=0이고 Bₘ=0입니다. 중심이 고정됐다는 뜻은 여전히 아닙니다.'),
      C('6 · 최종 확인 순서', 'r=R에서는 모든 J₀(αₘ)=0이라 테두리가 고정됩니다. r=0에서는 J₀(0)=1이고 기울기는 0이라 중심이 정상입니다. t=0에서 모드 합이 f, 시간 미분의 합이 g를 맞춥니다. 급수의 항별 미분은 초기함수의 매끄러움과 수렴을 확인한 범위에서 사용합니다.')
    ])
